USE_LEGACY_IDENTIFIERS_FOR_2004=false;
var USE_LEGACY_IDENTIFIERS_FOR_2004=false;

function getAPI(win) {
    console.log("[LMS Reset] Начинаем поиск LMS API");
    var attempts = 0;
    var maxAttempts = 500;

    while (win && attempts < maxAttempts) {
        console.log(`[LMS Reset] Попытка ${attempts + 1} из ${maxAttempts}`);

        try {
            if (win.API_1484_11) { // SCORM 2004
                console.log("[LMS Reset] Найден API_1484_11 (SCORM 2004)");
                return win.API_1484_11;
            } else if (win.API) { // SCORM 1.2
                console.log("[LMS Reset] Найден API (SCORM 1.2)");
                return win.API;
            }
        } catch (err) {
            console.warn("[LMS Reset] Ошибка доступа к окну:", err);
        }

        attempts++;
        if (win.parent && win.parent !== win) {
            win = win.parent;
        } else {
            break;
        }
    }

    console.error("[LMS Reset] Не удалось найти LMS API после 500 попыток");
    return null;
}

function resetInteractions() {
    console.log("[LMS Reset] Начало процесса сброса взаимодействий");

    try {
        // Получаем плеер Storyline
        var player = GetPlayer();
        if (!player) {
            console.error("[LMS Reset] Не удалось получить плеер Storyline");
            return false;
        }
        console.log("[LMS Reset] Плеер Storyline успешно получен");

        // Используем стандартный алгоритм поиска LMS API
        var lmsAPI = getAPI(window);

        if (!lmsAPI) {
            console.error("[LMS Reset] Не удалось найти LMS API");
            player.SetVar("resetStatus", "Не удалось найти LMS API");
            return false;
        } else {
            console.log("[LMS Reset] LMS API успешно получен");
        }

        // Определяем, SCORM 1.2 или SCORM 2004
        var isSCORM2004 = !!lmsAPI.Initialize;
        console.log(`[LMS Reset] Используется ${isSCORM2004 ? "SCORM 2004" : "SCORM 1.2"}`);

        // Проверяем, инициализирован ли сеанс
        var lmsInitialized = false;
        if (isSCORM2004) {
            lmsInitialized = lmsAPI.GetValue("cmi.entry") !== "";
        } else {
            lmsInitialized = lmsAPI.LMSGetValue("cmi.core.entry") !== "";
        }

        if (!lmsInitialized) {
            console.log("[LMS Reset] Сеанс не инициализирован, пытаемся инициализировать");
            var initSuccess = isSCORM2004 ? lmsAPI.Initialize("") : lmsAPI.LMSInitialize("");
            if (initSuccess.toString() !== "true") {
                var errorCode = isSCORM2004 ? lmsAPI.GetLastError() : lmsAPI.LMSGetLastError();
                var errorString = isSCORM2004 ? lmsAPI.GetErrorString(errorCode) : lmsAPI.LMSGetErrorString(errorCode);
                console.error(`[LMS Reset] Не удалось инициализировать сеанс с LMS`);
                console.error(`[LMS Reset] Код ошибки: ${errorCode}, описание: ${errorString}`);
                player.SetVar("resetStatus", "Ошибка инициализации сеанса с LMS");
                return false;
            } else {
                console.log("[LMS Reset] Сеанс с LMS успешно инициализирован");
            }
        } else {
            console.log("[LMS Reset] Сеанс уже инициализирован");
        }

        // Функции безопасного получения и установки значений
        function safeGetValue(key) {
            try {
                var value = isSCORM2004 ? lmsAPI.GetValue(key) : lmsAPI.LMSGetValue(key);
                var errorCode = isSCORM2004 ? lmsAPI.GetLastError() : lmsAPI.LMSGetLastError();
                if (errorCode !== "0") {
                    var errorString = isSCORM2004 ? lmsAPI.GetErrorString(errorCode) : lmsAPI.LMSGetErrorString(errorCode);
                    console.warn(`[LMS Reset] Ошибка получения ${key}: ${errorString} (код ${errorCode})`);
                    return "";
                } else {
                    console.log(`[LMS Reset] Получено значение ${key}: ${value}`);
                    return value;
                }
            } catch (error) {
                console.warn(`[LMS Reset] Исключение при получении ${key}:`, error);
                return "";
            }
        }

        function safeSetValue(key, value) {
            try {
                var result = isSCORM2004 ? lmsAPI.SetValue(key, value) : lmsAPI.LMSSetValue(key, value);
                var errorCode = isSCORM2004 ? lmsAPI.GetLastError() : lmsAPI.LMSGetLastError();
                if (errorCode !== "0") {
                    var errorString = isSCORM2004 ? lmsAPI.GetErrorString(errorCode) : lmsAPI.LMSGetErrorString(errorCode);
                    console.warn(`[LMS Reset] Ошибка установки ${key}: ${errorString} (код ${errorCode})`);
                    return false;
                } else {
                    console.log(`[LMS Reset] Установлено значение ${key}: ${value}`);
                    return true;
                }
            } catch (error) {
                console.warn(`[LMS Reset] Исключение при установке ${key}:`, error);
                return false;
            }
        }

        // Получаем количество взаимодействий
        var interactionCountKey = isSCORM2004 ? "cmi.interactions._count" : "cmi.core.interactions._count";
        var interactionCount = parseInt(safeGetValue(interactionCountKey), 10) || 0;
        console.log(`[LMS Reset] Найдено взаимодействий: ${interactionCount}`);

        // Сброс параметра learner_response для всех взаимодействий
        for (var j = 0; j < interactionCount; j++) {
            console.log(`[LMS Reset] Обработка взаимодействия ${j}`);
            var interactionPrefix = `cmi.interactions.${j}`;
            var interactionTypeKey = `${interactionPrefix}.type`;
            var interactionType = safeGetValue(interactionTypeKey);
            console.log(`[LMS Reset] Тип взаимодействия: ${interactionType}`);

            var resetValues = [];

            // Определяем возможные значения для сброса на основе типа взаимодействия
            switch (interactionType) {
                case "true-false":
                    resetValues = ["true", "false", ""];
                    break;
                case "choice":
        		case "sequencing":
            		resetValues = ["", null, "null", "~"];
            		break;
                case "fill-in":
                    resetValues = [""];
                    break;
                case "matching":
                    resetValues = ["", "A.B", "C.D"];
                    break;
                case "performance":
                    resetValues = [""];
                    break;
                case "likert":
                    resetValues = ["", "1", "2", "3", "4", "5"];
                    break;
                case "numeric":
                    resetValues = ["0", "1", "-1", ""];
                    break;
                default:
                    resetValues = [""];
                    break;
            }

            var success = false;
            for (var i = 0; i < resetValues.length; i++) {
                var valueToSet = resetValues[i];
                console.log(`[LMS Reset] Пытаемся установить learner_response: '${valueToSet}'`);
                success = safeSetValue(`${interactionPrefix}.learner_response`, valueToSet);
                if (success) {
                    console.log(`[LMS Reset] Успешно сброшен learner_response для взаимодействия ${j} со значением '${valueToSet}'`);
                    break;
                }
            }
            if (!success) {
                console.warn(`[LMS Reset] Не удалось сбросить learner_response для взаимодействия ${j}`);
            }
        }

        // Фиксация изменений
        var commitSuccess = isSCORM2004 ? lmsAPI.Commit("") : lmsAPI.LMSCommit("");
        if (commitSuccess.toString() === "true") {
            console.log("[LMS Reset] Изменения успешно зафиксированы");
        } else {
            var errorCode = isSCORM2004 ? lmsAPI.GetLastError() : lmsAPI.LMSGetLastError();
            var errorString = isSCORM2004 ? lmsAPI.GetErrorString(errorCode) : lmsAPI.LMSGetErrorString(errorCode);
            console.error("[LMS Reset] Ошибка при фиксации изменений");
            console.error(`[LMS Reset] Код ошибки при фиксации: ${errorCode}, описание: ${errorString}`);
        }

        // Завершаем сеанс
        var finishSuccess = isSCORM2004 ? lmsAPI.Terminate("") : lmsAPI.LMSFinish("");
        if (finishSuccess.toString() === "true") {
            console.log("[LMS Reset] Сеанс с LMS успешно завершен");
        } else {
            var errorCode = isSCORM2004 ? lmsAPI.GetLastError() : lmsAPI.LMSGetLastError();
            var errorString = isSCORM2004 ? lmsAPI.GetErrorString(errorCode) : lmsAPI.LMSGetErrorString(errorCode);
            console.warn("[LMS Reset] Ошибка при завершении сеанса с LMS");
            console.warn(`[LMS Reset] Код ошибки при завершении сеанса: ${errorCode}, описание: ${errorString}`);
        }

        // Устанавливаем переменную в Storyline для подтверждения
        player.SetVar("resetStatus", "Сброс успешен");
        console.log("[LMS Reset] Сброс завершен успешно");

        return true;
    } catch (globalError) {
        console.error("[LMS Reset] Критическая ошибка:", globalError);
        var player = GetPlayer();
        player.SetVar("resetStatus", "Критическая ошибка при сбросе");
        return false;
    } finally {
        console.log("[LMS Reset] Процесс сброса завершен");
    }
}

// Немедленный запуск функции
resetInteractions();

var player = GetPlayer();

// Получаем текущую дату и время
var currentDate = new Date();

// Добавляем 15 минут к текущему времени
var futureDate = new Date(currentDate.getTime() + 15 * 60 * 1000);

// Преобразуем дату в формат ДД:ММ:ГГГГ
var day = futureDate.getDate();
var month = futureDate.getMonth() + 1; // Месяцы в JavaScript начинаются с 0
var year = futureDate.getFullYear();

// Форматируем день и месяц с ведущим нулем
day = day < 10 ? '0' + day : day;
month = month < 10 ? '0' + month : month;

// Преобразуем время в формат ЧЧ:ММ:СС
var hours = futureDate.getHours();
var minutes = futureDate.getMinutes();
var seconds = futureDate.getSeconds();

// Форматируем часы, минуты и секунды с ведущим нулем
hours = hours < 10 ? '0' + hours : hours;
minutes = minutes < 10 ? '0' + minutes : minutes;
seconds = seconds < 10 ? '0' + seconds : seconds;

// Создаем строку в формате ДД:ММ:ГГГГ ЧЧ:ММ:СС
var formattedDateUnblock = day + ":" + month + ":" + year + " " + hours + ":" + minutes + ":" + seconds;

// Устанавливаем значение переменной Date_Unblock
player.SetVar("Date_Unblock", formattedDateUnblock);

var player = GetPlayer();

// Функция для преобразования времени в формате ММ:СС в минуты
function convertToMinutes(timeStr) {
  var parts = timeStr.split(":");
  var minutes = parseInt(parts[0], 10); // получаем минуты
  return minutes;
}

// Массив для хранения названий переменных времени
var timeVars = ["Time_1", "Time_2", "Time_3", "Time_4", "Time_5", "Time_6"];
var timeMinVars = ["Time_Min_1", "Time_Min_2", "Time_Min_3", "Time_Min_4", "Time_Min_5", "Time_Min_6"];

// Проходим по всем переменным времени
for (var i = 0; i < timeVars.length; i++) {
  var timeValue = player.GetVar(timeVars[i]); // Получаем значение переменной времени
  var minutes = convertToMinutes(timeValue); // Преобразуем в минуты
  player.SetVar(timeMinVars[i], minutes); // Устанавливаем значение переменной с минутами
}

